import (
	"fmt"
	"iter"
)

func Count(n int) iter.Seq[int] {
	return func(yield func(int) bool) {
		for i := 0; i < n; i++ {
			yield(i)
		}
	}
}

func main() {
	for v := range Count(5) {
		fmt.Println(v)
		if v == 1 {
			break
		}
	}
}

